Object.keys(KFU_PHARM).forEach(function(k){ if(!COURSE_ENRICHMENT[k]) COURSE_ENRICHMENT[k] = KFU_PHARM[k]; });


/* KFU + other programmes: graduation projects, training and research courses share one honest generic entry each;
   a few more electives reuse the equivalent enriched course. */
const KFU_RESEARCH = {"explain": {"ar": "البحث العلمي / المقرر البحثي: دراسة بحثية موجهة — اختيار موضوع، وقراءة أبحاث سابقة، وتنفيذ عمل صغير وكتابته. يحدد مشرفك التفاصيل.", "en": "Research course: a guided study — choosing a topic, reading prior work, doing a small piece of work and writing it up; your supervisor sets the details."}, "why": {"ar": "تعطيك تجربة مبكرة في الأبحاث، وهي شرط للدراسات العليا وتميز سيرتك الذاتية.", "en": "It gives early research experience, a requirement for postgraduate study and a strong CV line."}, "resources": [{"title": {"ar": "Research Methods Knowledge Base — مرجع مفتوح (مجاني)", "en": "Research Methods Knowledge Base (Free)"}, "url": "https://conjointly.com/kb/", "lang": "en", "partial": true, "reason": {"ar": "صياغة السؤال والتصاميم والعينات والقياس والتحليل — بلغة مبسّطة", "en": "Questions, designs, sampling and analysis in plain language"}}, {"title": {"ar": "Purdue OWL — الكتابة الأكاديمية والمهنية (مجاني)", "en": "Purdue OWL — Academic and Professional Writing (Free)"}, "url": "https://owl.purdue.edu/owl/general_writing/academic_writing/index.html", "lang": "en", "partial": true, "covers": "بناء الفقرة والحجة والنبرة المهنية، ووضوح الجملة، وتنظيم التقرير", "gap": "لا يغطي قوالب التقارير الهندسية تحديدًا (كمواصفات المشروع)، فقط مبادئ الكتابة الواضحة العامة", "reason": {"ar": "مصدر Purdue الرسمي لمهارات الكتابة الأكاديمية والمهنية، مجاني وبلا تسجيل. يغطي بالضبط ما يحتاجه أي تقرير هندسي: جملة واضحة، فقرة منظمة، وحجة مقنعة بلا حشو", "en": "Purdue's official resource for academic and professional writing skills, free with no registration. Covers exactly what any engineering report needs: a clear sentence, an organized paragraph, and a convincing argument without padding"}}]};
