/* LONGEST_FIRST: the app finds a course's entry by "the first key its catalog name starts with". A short key such as
   "BU8099" would then win over the more specific "BU8099T". Re-inserting the keys longest-first makes the specific one win. */
function reorderEnrichmentLongestFirst(){
  Object.keys(COURSE_ENRICHMENT).filter(function(k){ return !/^\d+$/.test(k); }).sort(function(a,b){ return b.length - a.length; }).forEach(function(k){ var v = COURSE_ENRICHMENT[k]; delete COURSE_ENRICHMENT[k]; COURSE_ENRICHMENT[k] = v; });
}
