function enrichmentForCourse(courseName){
  if(!courseName) return null;
  const code = Object.keys(COURSE_ENRICHMENT).find(c => courseName.trim().startsWith(c));
  return code ? COURSE_ENRICHMENT[code] : null;
}
/* A one-line honest label under each resource link, so the student knows what
   they're opening before they open it. The kind (video / PDF / site) is read
   off the URL so it can never go stale. Language and "covers part of the
   course" are only shown when we have actually confirmed them — an unknown
   field simply shows nothing rather than a guess. */
/* An English resource behind a translate proxy, so a student who reads Arabic
   only can still use it. We don't translate or re-host anything ourselves —
   this is the same page-translation the browser offers, reached in one tap
   instead of five. It only works on ordinary web pages: a PDF or a video
   can't be rewritten this way, so we return nothing for those rather than
   hand the student a link that opens on a blank page. */
function arabicVersionUrl(url){
  if(!url) return null;
  if(/youtube\.com|youtu\.be|\.pdf(\?|$)/i.test(url)) return null;
  const m = url.match(/^https?:\/\/([^\/]+)(\/.*)?$/);
  if(!m) return null;
  const host = m[1].replace(/-/g, "--").replace(/\./g, "-");
  const rest = m[2] || "/";
  return "https://" + host + ".translate.goog" + rest +
    (rest.indexOf("?") === -1 ? "?" : "&") + "_x_tr_sl=auto&_x_tr_tl=ar&_x_tr_hl=ar";
}
function arabicVersionLink(r, L){
  if(r.lang !== "en") return "";
  const u = arabicVersionUrl(r.url);
  if(!u) return "";
  const label = L === "ar" ? "اقرأها بالعربية ↗" : "Read it in Arabic ↗";
  return `<span class="translate-chip" data-translate-url="${u}">${label}</span>`;
}
