let fgHave = [];
let fgWant = null;
let fgField = "phys";

function fgMatches(){
  return LAWS.filter(L=>{
    if(L.f !== fgField) return false;
    if(fgWant && L.gives.indexOf(fgWant) === -1) return false;
    if(!fgHave.length) return !!fgWant;
    /* A law is offered when the student holds every quantity it needs — and
       gravity is assumed known rather than demanded of them. */
    return L.needs.every(q=>fgHave.indexOf(q) !== -1 || q === "g");
  });
}
/* ============================================================
   PERIODIC TABLE — an engineer's questions, not a chemist's
   ------------------------------------------------------------
   Public periodic tables lead with electron configuration and atomic radius. A
   chemical engineering student in the middle of a mass balance is asking three
   things: what is its molar mass, what state is it in at operating
   temperature, and where does it change. So those come first, and the molar
   mass is one tap away rather than one screen away.
   ============================================================ */
